// Package calibrate 是本地器具校准与证书的本地台账。
//
// 台账只保存在本机指定文件中，不连接任何真实实验室。多次打开同一文件
// 可以继续查询与操作，不同文件之间的数据互不相干。
package calibrate

import (
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// 日期布局，所有入参日期都必须是实际存在的 YYYY-MM-DD。
const DateLayout = "2006-01-02"

// Status 是器具的运行状态。
type Status string

const (
	// StatusPending 表示待校准，新登记器具的初始状态。
	StatusPending Status = "待校准"
	// StatusInUse 表示在用；在用本身不代表已经校准。
	StatusInUse Status = "在用"
	// StatusRetired 表示停用；停用不删除证书与使用记录。
	StatusRetired Status = "停用"
)

// ParseStatus 把命令行或文件中的状态文本解析为 Status。
func ParseStatus(s string) (Status, error) {
	switch strings.TrimSpace(s) {
	case string(StatusPending), "pending":
		return StatusPending, nil
	case string(StatusInUse), "in-use", "in_use":
		return StatusInUse, nil
	case string(StatusRetired), "retired":
		return StatusRetired, nil
	default:
		return "", fmt.Errorf("无效状态 %q：只能是 在用、停用 或 待校准", s)
	}
}

// Instrument 是登记的器具信息。
type Instrument struct {
	ID           string  `json:"id"`
	Name         string  `json:"name"`
	AllowedError float64 `json:"allowed_error"`
	Status       Status  `json:"status"`
	RegisteredAt string  `json:"registered_at"`
}

// Certificate 是一张校准证书。
type Certificate struct {
	Number       string  `json:"number"`
	InstrumentID string  `json:"instrument_id"`
	CalDate      string  `json:"cal_date"`
	Expiry       string  `json:"expiry"`
	Method       string  `json:"method"`
	Error        float64 `json:"error"`
	Summary      string  `json:"summary"`
	CreatedAt    string  `json:"created_at"`
}

// Pass 按证书自身数据判断是否合格：测得误差绝对值不超过允许误差（含限值）。
// 结论由数据计算，录入者不能自行选择。
func (c Certificate) Pass(allowedError float64) bool {
	return math.Abs(c.Error) <= allowedError
}

// UsageRecord 是一次使用申请的留痕，原因在申请发生时冻结。
type UsageRecord struct {
	InstrumentID string   `json:"instrument_id"`
	RequestedAt  string   `json:"requested_at"`
	Allowed      bool     `json:"allowed"`
	Reasons      []string `json:"reasons"`
}

// ledgerData 是台账文件的持久化结构。
type ledgerData struct {
	Version      int           `json:"version"`
	Instruments  []Instrument  `json:"instruments"`
	Certificates []Certificate `json:"certificates"`
	Usage        []UsageRecord `json:"usage"`
	Plans        []Plan        `json:"plans,omitempty"`
}

// Ledger 是一份可操作的本地台账。
type Ledger struct {
	path string
	now  func() time.Time
	data ledgerData
}

// ValidationError 表示输入未通过业务校验，调用方不会改动任何已有记录。
type ValidationError struct{ Msg string }

func (e *ValidationError) Error() string { return e.Msg }

func validationError(format string, args ...any) error {
	return &ValidationError{Msg: fmt.Sprintf(format, args...)}
}

// IsValidation 报告 err 是否为业务校验错误。
func IsValidation(err error) bool {
	var v *ValidationError
	return errors.As(err, &v)
}

// ConflictError 表示同号证书内容不一致等冲突，已有数据保持不变。
type ConflictError struct{ Msg string }

func (e *ConflictError) Error() string { return e.Msg }

// IsConflict 报告 err 是否为冲突错误。
func IsConflict(err error) bool {
	var c *ConflictError
	return errors.As(err, &c)
}

// ErrNotFound 表示编号在台账中不存在。
var ErrNotFound = errors.New("记录不存在")

func cleanText(s string) (string, error) {
	t := strings.TrimSpace(s)
	if t == "" {
		return "", validationError("不能留空或只有空白")
	}
	return t, nil
}

func parseFiniteDate(s, field string) (time.Time, string, error) {
	t := strings.TrimSpace(s)
	if t == "" {
		return time.Time{}, "", validationError("%s不能留空", field)
	}
	parsed, err := time.Parse(DateLayout, t)
	if err != nil {
		return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
	}
	// time.Parse 对 YYYY-MM-DD 遇到超范围日期会直接报错；再用 Format
	// 往返一次，拒绝 2024-2-3 之类格式不符的输入。
	if parsed.Format(DateLayout) != t {
		return time.Time{}, "", validationError("%s必须是实际存在的日期（格式 YYYY-MM-DD）", field)
	}
	return parsed, t, nil
}

func finiteNumber(v float64, field string) error {
	if math.IsNaN(v) || math.IsInf(v, 0) {
		return validationError("%s必须是有限数", field)
	}
	return nil
}

// Open 打开 path 所指的本机台账；文件不存在时建立一份新台账。
// 同一文件可以反复打开继续操作，不同 path 的数据互不混入。
func Open(path string) (*Ledger, error) {
	return openAt(path, time.Now)
}

func openAt(path string, now func() time.Time) (*Ledger, error) {
	if strings.TrimSpace(path) == "" {
		return nil, fmt.Errorf("台账文件路径不能为空")
	}
	l := &Ledger{
		path: path,
		now:  now,
		data: ledgerData{Version: 1},
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return l, nil
		}
		return nil, fmt.Errorf("读取台账 %s: %w", path, err)
	}
	if len(raw) > 0 {
		if err := json.Unmarshal(raw, &l.data); err != nil {
			return nil, fmt.Errorf("台账文件 %s 已损坏: %w", path, err)
		}
	}
	if l.data.Version == 0 {
		l.data.Version = 1
	}
	return l, nil
}

// Path 返回台账文件位置。
func (l *Ledger) Path() string { return l.path }

// save 把当前台账完整写回文件：先写临时文件再原子改名，
// 保证无效录入中断时不会留下半份记录。
func (l *Ledger) save() error {
	if err := os.MkdirAll(filepath.Dir(l.path), 0o755); err != nil {
		return fmt.Errorf("写入台账文件 %s 前创建目录失败: %w", l.path, err)
	}
	raw, err := json.MarshalIndent(l.data, "", "  ")
	if err != nil {
		return fmt.Errorf("序列化台账 %s: %w", l.path, err)
	}
	raw = append(raw, '\n')
	tmp, err := os.CreateTemp(filepath.Dir(l.path), ".ledger-*.tmp")
	if err != nil {
		return fmt.Errorf("为台账 %s 创建临时文件: %w", l.path, err)
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName)
	if _, err := tmp.Write(raw); err != nil {
		tmp.Close()
		return fmt.Errorf("写入台账 %s 的临时文件: %w", l.path, err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("关闭台账 %s 的临时文件: %w", l.path, err)
	}
	if err := os.Rename(tmpName, l.path); err != nil {
		return fmt.Errorf("替换台账文件 %s: %w", l.path, err)
	}
	return nil
}

func (l *Ledger) findInstrument(id string) *Instrument {
	for i := range l.data.Instruments {
		if l.data.Instruments[i].ID == id {
			return &l.data.Instruments[i]
		}
	}
	return nil
}

// Instrument 按编号返回登记器具的独立副本；编号不存在时返回包装了
// ErrNotFound 的错误。它只读取该器具自身的登记信息，不组装历史证书、
// 使用拒绝记录或校准计划：显示一张证书的结论只需要证书自身的测得误差
// 与该器具登记的允许误差，不需要完整核对结果。
func (l *Ledger) Instrument(id string) (*Instrument, error) {
	inst := l.findInstrument(id)
	if inst == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
	}
	saved := *inst
	return &saved, nil
}

func (l *Ledger) findCertificate(number string) *Certificate {
	for i := range l.data.Certificates {
		if l.data.Certificates[i].Number == number {
			return &l.data.Certificates[i]
		}
	}
	return nil
}

// RegisterInput 是登记器具的输入。
type RegisterInput struct {
	ID           string
	Name         string
	AllowedError float64
}

// Register 登记一件新器具。编号、名称不得为空白，允许误差必须是不小于零的
// 有限数；编号重复或输入无效时明确拒绝，原记录不变。新器具处于待校准状态。
//
// 只有本次保存成功，新器具才算正式登记：若台账文件无法写入或替换，明确返回
// 保存错误而不返回已登记的器具，台账（含同一对象随后的列出、按编号核对、
// 编号占用判断以及校准与使用安排）与登记前完全一致——失败的器具不出现在列表、
// 不占用编号，也不会在此后其他成功操作写盘时被顺带写入；文件仍不可写时再次
// 提交同号合法内容仍报保存错误（不会因内存里残留的失败器具而被当成编号重复）。
// 恢复可写后无需重新打开台账，重新提交且保存成功才新增一件待校准器具，
// 登记时间、名称与允许误差均取本次成功提交的内容，不沿用失败申请；成功后
// 再登记同号仍按编号唯一拒绝。未通过业务校验的申请仍按原有方式拒绝，
// 不会因台账不可写而被混成保存失败。
func (l *Ledger) Register(in RegisterInput) (*Instrument, error) {
	id, err := cleanText(in.ID)
	if err != nil {
		return nil, fmt.Errorf("器具编号无效：%w", err)
	}
	name, err := cleanText(in.Name)
	if err != nil {
		return nil, fmt.Errorf("器具名称无效：%w", err)
	}
	if err := finiteNumber(in.AllowedError, "允许的绝对误差"); err != nil {
		return nil, err
	}
	if in.AllowedError < 0 {
		return nil, validationError("允许的绝对误差不能小于零")
	}
	if l.findInstrument(id) != nil {
		return nil, validationError("器具编号 %s 已存在，编号必须唯一", id)
	}
	inst := Instrument{
		ID:           id,
		Name:         name,
		AllowedError: in.AllowedError,
		Status:       StatusPending,
		RegisteredAt: l.now().Format(time.RFC3339),
	}
	// 在独立的新切片上暂存新器具：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片，保证同一台账对象随后的列出、按编号核对与编号
	// 占用判断都与登记前一致，失败器具也不会被之后的写盘顺带写入。
	original := l.data.Instruments
	staged := make([]Instrument, 0, len(original)+1)
	staged = append(staged, original...)
	staged = append(staged, inst)
	l.data.Instruments = staged
	if err := l.save(); err != nil {
		l.data.Instruments = original
		return nil, err
	}
	// 返回已保存器具的独立副本：返回结果只表示本次保存成功的内容。
	saved := *l.findInstrument(id)
	return &saved, nil
}

// SetStatus 切换器具状态。切换为在用不代表已校准；停用不删除证书与使用记录。
//
// 目标状态合法且与最后成功保存的状态不同后才写盘：若台账文件无法写入或替换，
// 明确返回保存错误，台账（含同一对象随后的列出、按器具核对、待办与使用判断）
// 与切换前完全一致——器具仍保持最后成功保存的状态，失败的目标状态既不会提前
// 参与使用资格判断，也不会在此后其他成功操作写盘时被顺带写入；文件仍不可写时
// 再次提交同一目标状态仍报保存错误（不会因内存已被改成目标状态而被当成
// “状态未变”跳过保存返回成功）。恢复可写后无需重新打开台账，重新提交且保存
// 成功，新状态才生效。请求状态本来就等于最后成功保存的状态时直接成功，不写盘。
func (l *Ledger) SetStatus(id string, status Status) error {
	switch status {
	case StatusInUse, StatusRetired, StatusPending:
	default:
		return validationError("无效状态：只能是 在用、停用 或 待校准")
	}
	inst := l.findInstrument(id)
	if inst == nil {
		return fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
	}
	if inst.Status == status {
		return nil
	}
	// 在整份器具切片的独立副本上暂存新状态：只有原子替换台账文件成功后才
	// 提交。写盘失败时恢复原切片，保证同一台账对象随后看到的器具状态、列出
	// 结果、待办与使用判断都与切换前一致；再次提交相同状态仍会走到保存，
	// 失败状态也不会被之后的写盘顺带写入。
	original := l.data.Instruments
	staged := make([]Instrument, len(original))
	copy(staged, original)
	for i := range staged {
		if staged[i].ID == id {
			staged[i].Status = status
			break
		}
	}
	l.data.Instruments = staged
	if err := l.save(); err != nil {
		l.data.Instruments = original
		return err
	}
	return nil
}

// CertificateInput 是录入校准证书的输入。
type CertificateInput struct {
	InstrumentID string
	Number       string
	CalDate      string
	Expiry       string
	Method       string
	Error        float64
	Summary      string
}

// AddCertificate 录入一张校准证书并返回它；若同号证书且全部业务字段一致，
// 返回原证书且不增加历史（幂等）。同号内容不同报冲突且不改动已有数据。
//
// 同号判定优先于“校准日期不能晚于本机今天”：证书首次录入时内容合法且已
// 成功保存，之后本机调整时区或日期、使当前日历日期落到该证书校准日期
// 之前，再原样提交同号证书仍幂等成功并返回首次保存的原证书（保留首次
// 录入时间，不新增历史、不切换器具状态、不新增使用申请）；同号但修改了
// 校准方法、摘要或测得误差等任一字段时，仍报同号内容冲突而不是未来日期
// 错误，原证书不被覆盖。只有台账中不存在的新编号才受“校准日期不能晚于
// 本机今天”约束，本机日期正常推进时的新录入行为保持不变。
//
// 返回的证书只是本次已保存内容的展示副本，与台账内存储不共享内存：调用方
// 整理返回结果中的误差、截止日、编号或其他字段，不会改写台账里的正式证书，
// 不影响最近证书的选择、使用资格判断与编号占用，也不会被此后的写盘带入文件；
// 重新查询得到的仍是实际保存的内容。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的查询）与录入前完全一致——失败的证书既不进入历史、
// 不占用证书编号或该器具当天的位置，也不会在此后其他成功操作写盘时被顺带写入；
// 恢复可写后重新提交同号同内容会作为新证书正常录入。
func (l *Ledger) AddCertificate(in CertificateInput) (*Certificate, bool, error) {
	instID, err := cleanText(in.InstrumentID)
	if err != nil {
		return nil, false, fmt.Errorf("器具编号无效：%w", err)
	}
	number, err := cleanText(in.Number)
	if err != nil {
		return nil, false, fmt.Errorf("证书编号无效：%w", err)
	}
	method, err := cleanText(in.Method)
	if err != nil {
		return nil, false, fmt.Errorf("校准方法无效：%w", err)
	}
	summary, err := cleanText(in.Summary)
	if err != nil {
		return nil, false, fmt.Errorf("摘要无效：%w", err)
	}
	if err := finiteNumber(in.Error, "测得误差"); err != nil {
		return nil, false, err
	}

	inst := l.findInstrument(instID)
	if inst == nil {
		return nil, false, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
	}

	_, calText, err := parseFiniteDate(in.CalDate, "校准日期")
	if err != nil {
		return nil, false, err
	}
	_, expText, err := parseFiniteDate(in.Expiry, "有效期截止日")
	if err != nil {
		return nil, false, err
	}
	if expText <= calText {
		return nil, false, validationError("有效期截止日 %s 必须晚于校准日期 %s", expText, calText)
	}

	// 同号判定优先于“校准日期不能晚于本机今天”：证书首次保存时内容合法，
	// 之后本机日期（含时区调整）回落到该证书校准日期之前，同号提交仍应按
	// 已有证书处理——内容一致幂等返回原证书，内容不同报冲突；本机日期变化
	// 不能让已有证书的重复提交变成一次失败的新录入。未来日期限制只约束
	// 台账中不存在的新证书编号。
	if existing := l.findCertificate(number); existing != nil {
		same := existing.InstrumentID == instID &&
			existing.CalDate == calText &&
			existing.Expiry == expText &&
			existing.Method == method &&
			existing.Summary == summary &&
			existing.Error == in.Error
		if !same {
			return nil, false, &ConflictError{Msg: fmt.Sprintf(
				"证书编号 %s 已存在且内容不同，拒绝覆盖已有数据", number)}
		}
		// 同号且全部业务字段一致：返回原证书，不增加历史记录。
		// 返回独立副本：调用方对返回结果的整理不能成为改写正式证书的途径。
		dup := *existing
		return &dup, true, nil
	}

	// 与“本机今天”按日历日期比较，避免时分秒和时区造成边界误差。
	// 新编号证书的校准日期晚于本机今天时直接拒绝：不新增证书，也不占用
	// 该编号或该器具当天的位置。
	todayText := l.now().Format(DateLayout)
	if calText > todayText {
		return nil, false, validationError("校准日期 %s 不能晚于本机今天 %s", calText, todayText)
	}
	// 同一器具同一天不接受两张不同编号的证书。
	for i := range l.data.Certificates {
		c := &l.data.Certificates[i]
		if c.InstrumentID == instID && c.CalDate == calText {
			return nil, false, validationError(
				"器具 %s 在 %s 已有证书 %s，同一天不能再登记不同编号的证书",
				instID, calText, c.Number)
		}
	}

	cert := Certificate{
		Number:       number,
		InstrumentID: instID,
		CalDate:      calText,
		Expiry:       expText,
		Method:       method,
		Error:        in.Error,
		Summary:      summary,
		CreatedAt:    l.now().Format(time.RFC3339),
	}
	// 在独立的新切片上暂存新证书：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片，保证同一台账对象随后看到的历史、最近证书、
	// 证书编号占用与同日位置都与录入前一致，且不会被之后的写盘顺带写入。
	original := l.data.Certificates
	staged := make([]Certificate, 0, len(original)+1)
	staged = append(staged, original...)
	staged = append(staged, cert)
	l.data.Certificates = staged
	if err := l.save(); err != nil {
		l.data.Certificates = original
		return nil, false, err
	}
	// 返回已保存证书的独立副本：返回结果只表示本次保存的内容，调用方的
	// 后续整理不会连带改写台账内的正式证书。
	saved := *l.findCertificate(number)
	return &saved, false, nil
}

// certNewer 是“最近证书”的唯一先后规则：校准日期较新者在前，与录入先后、
// 到期先后或合格结论无关；校准日期相同时（正常业务下同器具同日只允许一张）
// 按证书编号升序，保证并列时结果稳定。
func certNewer(a, b Certificate) bool {
	if a.CalDate != b.CalDate {
		return a.CalDate > b.CalDate
	}
	return a.Number < b.Number
}

// certificatesOf 收集并整理某器具的完整证书历史，按校准日期从新到旧排序。
// 只在确实需要完整历史的按器具核对中使用；只要最近证书的入口不应走这里，
// 避免为取一张证书而收集、排序整段历史。切片元素都是台账证书的独立副本。
func (l *Ledger) certificatesOf(id string) []Certificate {
	var out []Certificate
	for _, c := range l.data.Certificates {
		if c.InstrumentID == id {
			out = append(out, c)
		}
	}
	sort.Slice(out, func(i, j int) bool { return certNewer(out[i], out[j]) })
	return out
}

// latestOf 从已按 certNewer 排好序的证书中取出最近证书的独立副本；
// 空切片返回 nil。
func latestOf(certs []Certificate) *Certificate {
	if len(certs) == 0 {
		return nil
	}
	latest := certs[0]
	return &latest
}

// latestCertificate 只扫描一遍该器具自身的证书挑出最近一张，不收集、不排序
// 完整历史：只查询最近证书或判断能否使用时，不必承担整理整段历史的工作。
// 归属过滤保证其他器具的证书既不会混入也不会影响本器具的最近证书选择。
// 返回的是独立副本，调用方的整理不会回写台账。
func (l *Ledger) latestCertificate(id string) *Certificate {
	best := Certificate{}
	found := false
	for _, c := range l.data.Certificates {
		if c.InstrumentID != id {
			continue
		}
		if !found || certNewer(c, best) {
			best = c
			found = true
		}
	}
	if !found {
		return nil
	}
	latest := best
	return &latest
}

// LatestCertificate 返回器具按校准日期确定的最近证书；没有证书时返回 nil。
// 最近证书与录入先后、到期先后或合格结论无关，补录较早证书只增加历史、
// 不改变最近证书。它只挑出这一张证书，不组装完整历史；返回的是独立副本。
func (l *Ledger) LatestCertificate(id string) *Certificate {
	return l.latestCertificate(id)
}

// CertificateView 是证书及其在当前日期下的判定结果。
type CertificateView struct {
	Certificate
	Pass    bool `json:"pass"`
	Expired bool `json:"expired"`
}

func viewCertificate(c Certificate, allowed float64, today time.Time) CertificateView {
	return CertificateView{
		Certificate: c,
		Pass:        c.Pass(allowed),
		// 有效期截止日当天起即到期：按日历日期比较，今天 >= 截止日即为到期。
		Expired: today.Format(DateLayout) >= c.Expiry,
	}
}

// UsageDecision 是一次使用申请的评估结果，原因在申请时冻结留痕。
type UsageDecision struct {
	InstrumentID string
	Allowed      bool
	Reasons      []string
	Latest       *CertificateView
	evaluatedAt  time.Time
}

// decideUsage 按器具状态与“最近证书”判定 today 所在本机日历日期能否使用，
// 并列出全部适用原因。最近证书由调用方按 certNewer 确定后传入（只取最近一张
// 或来自完整历史均可）：最近证书超差或到期时不会回退到更早的合格证书。
// 同一次核对的各部分必须共用同一个 today，避免跨午夜时判断不一致。
func decideUsage(inst *Instrument, latest *Certificate, today time.Time) *UsageDecision {
	d := &UsageDecision{InstrumentID: inst.ID, evaluatedAt: today}
	if inst.Status != StatusInUse {
		d.Reasons = append(d.Reasons, fmt.Sprintf("器具当前状态为%s，只有在用器具可以申请使用", inst.Status))
	}
	if latest == nil {
		d.Reasons = append(d.Reasons, "没有校准证书")
	} else {
		v := viewCertificate(*latest, inst.AllowedError, today)
		d.Latest = &v
		if !v.Pass {
			d.Reasons = append(d.Reasons, fmt.Sprintf(
				"最近证书 %s 测得误差绝对值 %g 超过允许误差 %g，判定超差",
				latest.Number, math.Abs(latest.Error), inst.AllowedError))
		}
		if v.Expired {
			d.Reasons = append(d.Reasons, fmt.Sprintf("最近证书 %s 已于 %s 到期（截止日当天即到期）",
				latest.Number, latest.Expiry))
		}
	}
	d.Allowed = len(d.Reasons) == 0
	return d
}

// evaluateAt 按器具状态与“最近证书”判定 now 所在本机日历日期能否使用。
// 只查询能否使用时只扫描挑出最近证书（latestCertificate），不整理完整历史。
func (l *Ledger) evaluateAt(id string, now time.Time) (*Instrument, *UsageDecision) {
	inst := l.findInstrument(id)
	if inst == nil {
		return nil, nil
	}
	return inst, decideUsage(inst, l.latestCertificate(id), now)
}

// CanUse 只按当前数据评估能否使用，不留存申请记录。
func (l *Ledger) CanUse(id string) (*UsageDecision, error) {
	inst, d := l.evaluateAt(id, l.now())
	if inst == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
	}
	return d, nil
}

// cloneReasons 返回原因切片的独立副本，使对外返回的数据与台账内部存储
// 不共享底层数组：调用方替换、删减或补充返回结果中的原因，不会改写
// 已留痕的历史原因。nil 保持 nil，以维持空结果的既有表现。
func cloneReasons(in []string) []string {
	if in == nil {
		return nil
	}
	return append([]string(nil), in...)
}

// RequestUse 针对已有器具提交使用申请：无论允许或拒绝都保存申请时间、结果
// 与当时全部原因。未知编号报错且不新增记录。
//
// 只有本次记录保存成功，申请才算提交完成：若台账文件无法写入或替换，明确返回
// 保存错误而不返回评估结果，台账（含同一对象随后的全部使用记录与按器具核对中
// 的被拒绝记录）与申请前完全一致——本次申请的时间、允许结果与拒绝原因不进入
// 历史，也不会在此后其他成功操作写盘时被顺带写入；器具登记信息、证书与校准计划
// 不因这次失败发生变化。恢复可写后无需重新打开台账，在同一台账重新申请才会按
// 当时的器具状态与证书重新判断并新增一条记录。
func (l *Ledger) RequestUse(id string) (*UsageDecision, error) {
	if strings.TrimSpace(id) == "" {
		return nil, fmt.Errorf("器具编号无效：%w", validationError("不能留空或只有空白"))
	}
	inst, d := l.evaluateAt(id, l.now())
	if inst == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
	}
	// 留痕使用独立副本：返回给调用方的 d.Reasons 与其后的整理操作
	// 不能成为改写台账内历史原因的途径。
	rec := UsageRecord{
		InstrumentID: id,
		RequestedAt:  d.evaluatedAt.Format(time.RFC3339),
		Allowed:      d.Allowed,
		Reasons:      cloneReasons(d.Reasons),
	}
	if rec.Reasons == nil {
		rec.Reasons = []string{}
	}
	// 在独立的新切片上暂存本次申请：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片，保证同一台账对象随后看到的全部使用记录与
	// 按器具核对中的被拒绝记录都与申请前一致，失败申请也不会被之后的
	// 写盘顺带写入。
	original := l.data.Usage
	staged := make([]UsageRecord, 0, len(original)+1)
	staged = append(staged, original...)
	staged = append(staged, rec)
	l.data.Usage = staged
	if err := l.save(); err != nil {
		l.data.Usage = original
		return nil, err
	}
	return d, nil
}

// InstrumentReview 是按器具核对的完整视图。
type InstrumentReview struct {
	Instrument Instrument        `json:"instrument"`
	CanUse     bool              `json:"can_use"`
	Reasons    []string          `json:"reasons"`
	Latest     *CertificateView  `json:"latest"`
	History    []CertificateView `json:"history"`
	Rejections []UsageRecord     `json:"rejections"`
	Plans      []PlanView        `json:"plans"`
}

// Review 按器具核对：登记信息、当前能否使用及原因、最近证书与到期日、
// 全部历史证书、被拒绝的使用记录以及该器具当前与已结束的校准计划。
// 整份核对只采用核对开始时的一次本机日期：即使查询结束前跨过午夜，
// 能否使用、最近证书、历史证书到期判断与未结束计划标记也不会各自变成新一天。
// 历史拒绝原因按申请当时的冻结内容展示，不随本次采用的日期重新计算。
// 返回的证书、拒绝记录与计划（含改期历史）都是独立展示副本，调用方的
// 整理不回写台账，也不影响此前或之后分别取得的其他结果。
func (l *Ledger) Review(id string) (*InstrumentReview, error) {
	// 本次核对只在开始时取一次本机时间，整份结果共用，跨午夜不分裂判断；
	// 下一次核对会重新取当时的本机日期，不沿用本次结果。
	now := l.now()
	inst := l.findInstrument(id)
	if inst == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
	}
	// 核对需要完整历史：该器具的证书只收集、排序这一次。历史视图与最近证书
	// 都从同一份结果派生（最近证书即排序后的第一张），并共用同一个 today，
	// 不再为最近证书单独整理一遍历史——也保证同一张证书在最近证书与历史中
	// 编号、日期、误差、方法、摘要与到期判定完全一致，不会一边未到期一边到期。
	certs := l.certificatesOf(id)
	today := now
	d := decideUsage(inst, latestOf(certs), today)
	r := &InstrumentReview{
		Instrument: *inst,
		CanUse:     d.Allowed,
		Reasons:    d.Reasons,
		Latest:     d.Latest,
	}
	if r.Reasons == nil {
		r.Reasons = []string{}
	}
	// 历史沿用既有空结果表现：没有证书时保持 nil（普通输出显示“无”，
	// JSON 为 null）；有证书时按校准日期由近到远追加。
	for _, c := range certs {
		r.History = append(r.History, viewCertificate(c, inst.AllowedError, today))
	}
	for _, u := range l.data.Usage {
		if u.InstrumentID == id && !u.Allowed {
			// 逐条深拷贝原因：对外核对视图中的历史拒绝记录只是展示副本，
			// 调用方的整理不能回写台账，也不能影响其他入口已取得的结果。
			u.Reasons = cloneReasons(u.Reasons)
			r.Rejections = append(r.Rejections, u)
		}
	}
	r.Plans = l.planViews(id, today)
	return r, nil
}

// Instruments 返回全部登记器具的副本，按编号排序。
func (l *Ledger) Instruments() []Instrument {
	out := append([]Instrument(nil), l.data.Instruments...)
	sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
	return out
}

// parseInstant 把带偏移的 RFC3339 时间（如申请时间、计划建立时间，可带
// 不同偏移或 Z）解析为实际时刻。不同文字形式（如 Z 与 +00:00）只要表示
// 同一绝对时刻，解析结果即相同。
func parseInstant(s string) (time.Time, bool) {
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, false
	}
	return t, true
}

// UsageRecords 返回全部使用申请记录，按申请发生的实际时刻从早到晚排序。
//
// RequestedAt 是带偏移的 RFC3339 时间：同一份台账可保存于不同系统时区偏移
// （含 Z 与显式零偏移），排序时换算为同一基准下的绝对时刻，因此显示文字里
// 小时、分钟更大的记录未必更晚，跨日记录也按实际时刻排列；记录各自保存时的
// 偏移决定先后，查询当天的系统时区不能改变历史顺序。获准与被拒绝的申请一起
// 参与排序，申请结果不作为排序条件。实际时刻相同的记录按器具编号升序；同一
// 器具在同一时刻的多次申请保留其在台账中的原有次序，每条已保存申请都保留、
// 不合并。没有记录时返回空结果，只有一条时原样返回。
//
// 返回的是展示副本：申请时间保留原文字及偏移，器具编号、申请结果与拒绝原因
// 保持保存时的内容；整理其中原因不会改动台账内已冻结的留痕，也不会被后续
// 正常写盘带入文件。查询本身不新增使用申请、不写回台账。
func (l *Ledger) UsageRecords() []UsageRecord {
	out := append([]UsageRecord(nil), l.data.Usage...)
	for i := range out {
		out[i].Reasons = cloneReasons(out[i].Reasons)
	}
	sort.SliceStable(out, func(i, j int) bool {
		ti, oki := parseInstant(out[i].RequestedAt)
		tj, okj := parseInstant(out[j].RequestedAt)
		switch {
		case oki && okj:
			// 按实际时刻比较：Equal/Before 以绝对时刻为准，与记录保存时
			// 所带的偏移及文字形式无关。
			if !ti.Equal(tj) {
				return ti.Before(tj)
			}
		case oki != okj:
			// 时间文字无法解析的异常记录排到可解析记录之后，顺序仍确定；
			// 正常由本台账保存的 RFC3339 记录不会走到这里。
			return oki
		default:
			// 两条都无法解析时退回按原文字比较，保证结果确定。
			if out[i].RequestedAt != out[j].RequestedAt {
				return out[i].RequestedAt < out[j].RequestedAt
			}
		}
		// 实际时刻相同：按器具编号升序；编号也相同的同一时刻多次申请由
		// SliceStable 保留其在台账中的原有次序，不因获准/拒绝结果而变动。
		return out[i].InstrumentID < out[j].InstrumentID
	})
	return out
}

package calibrate

import (
	"fmt"
	"sort"
	"strings"
	"time"
)

// 计划状态：进行中的计划可改期、取消或完成；已完成与已取消均为终态，
// 不能再改期、取消或重新开启。
const (
	PlanStatusOpen     = "未完成"
	PlanStatusDone     = "已完成"
	PlanStatusCanceled = "已取消"
)

// 待办相对本机今天的标记。
const (
	TodoToday   = "今天需校准"
	TodoOverdue = "逾期"
	TodoFuture  = "未到计划日"
)

// PlanChange 记录一次改期：保留修改前后的日期、操作时间和原因。
type PlanChange struct {
	From      string `json:"from"`
	To        string `json:"to"`
	ChangedAt string `json:"changed_at"`
	Reason    string `json:"reason"`
}

// Plan 是一项校准计划。编号在全台账唯一，即使计划已结束编号也不再复用。
type Plan struct {
	Number       string `json:"number"`
	InstrumentID string `json:"instrument_id"`
	// PlannedDate 是当前计划日期；OriginalDate 保留建立时的计划日期。
	PlannedDate  string       `json:"planned_date"`
	OriginalDate string       `json:"original_date"`
	Note         string       `json:"note"`
	CreatedAt    string       `json:"created_at"`
	Changes      []PlanChange `json:"changes,omitempty"`
	Status       string       `json:"status"`
	// 取消时保留原计划日期、取消时间和原因。
	CanceledAt   string `json:"canceled_at,omitempty"`
	CancelReason string `json:"cancel_reason,omitempty"`
	// 完成时保存完成时间和所用证书编号。
	CompletedAt       string `json:"completed_at,omitempty"`
	CertificateNumber string `json:"certificate_number,omitempty"`
}

// Open 报告计划是否尚未结束（未完成、未取消）。
func (p Plan) Open() bool { return p.Status == PlanStatusOpen }

// PlanInput 是建立校准计划的输入。
type PlanInput struct {
	Number       string
	InstrumentID string
	Date         string
	Note         string
}

func (l *Ledger) findPlan(number string) *Plan {
	for i := range l.data.Plans {
		if l.data.Plans[i].Number == number {
			return &l.data.Plans[i]
		}
	}
	return nil
}

// cloneChanges 返回改期历史切片的独立副本，使对外返回的计划与台账内部
// 存储不共享底层数组：调用方调换顺序、删改或追加展示用记录，不会改写
// 正式的改期历史。nil 保持 nil，以维持“没有改期历史”的既有表现。
func cloneChanges(in []PlanChange) []PlanChange {
	if in == nil {
		return nil
	}
	return append([]PlanChange(nil), in...)
}

// clonePlan 返回计划的独立深拷贝，连同改期历史一起复制。
func clonePlan(p Plan) Plan {
	p.Changes = cloneChanges(p.Changes)
	return p
}

// clonePlanPtr 返回台账内计划的独立深拷贝；找不到时返回 nil。
// 各计划操作返回的计划只是已保存内容的展示副本：调用方为了显示而改动
// 编号、日期、状态、关联证书或改期记录，都不能成为绕过计划操作直接改写
// 台账的途径，也不会在此后正常写盘时被带入台账文件。
func clonePlanPtr(p *Plan) *Plan {
	if p == nil {
		return nil
	}
	cp := clonePlan(*p)
	return &cp
}

// validatePlanDate 解析 YYYY-MM-DD 真实日期，且不得早于 now 所在的本机
// 日历日期。调用方传入本次操作开始时所取的本机时间，使日期合法性与操作
// 记录的时间对应同一时刻。
func (l *Ledger) validatePlanDate(raw, field string, now time.Time) (string, error) {
	_, text, err := parseFiniteDate(raw, field)
	if err != nil {
		return "", err
	}
	todayText := now.Format(DateLayout)
	if text < todayText {
		return "", validationError("%s %s 不能早于本机今天 %s", field, text, todayText)
	}
	return text, nil
}

// CreatePlan 为已登记器具建立一项校准计划。计划编号全台账唯一（即使对应
// 已结束计划也不能复用），计划日期须真实存在且不早于本机今天，说明非空；
// 每件器具最多有一项未完成、未取消的计划。任一条件不满足都明确拒绝，
// 不新增或改动任何记录。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的计划查询、按器具核对与待办）与建立前完全一致——
// 失败的计划既不占用编号，也不占用该器具唯一的未结束计划名额，更不会在此后
// 其他成功操作写盘时被顺带写入；文件仍不可写时再次提交相同编号仍报保存错误
// （不会被当成编号重复或器具已有未结束计划而拒绝），恢复可写后无需重新打开
// 台账，重新提交才真正建立，建立时间取本次成功申请的时间。
//
// 返回的计划只是已保存内容的展示副本，与台账内存储不共享内存：调用方为
// 显示而改动编号、日期、状态或关联证书，不占用或释放正式计划编号，不影响
// 每件器具最多一项未结束计划的判断，也不会在此后正常写盘时被带入台账文件；
// 重新查询同一台账得到的仍是最后成功保存的计划。
// 每次建立申请只在开始处理时取一次本机时间：计划日期是否不早于“今天”
// 按该时刻的日历日期判断，正式保存的建立时间也取该时刻——即使校验与写盘
// 之间跨过午夜，建立时间仍属于申请开始的日历日期，当天计划不会被记成
// 次日建立，也不会在随后用申请当天的证书完成时被误判为证书早于建立。
// 该时刻不延续到下一次申请：下次建立重新取当时的本机时间判断。
func (l *Ledger) CreatePlan(in PlanInput) (*Plan, error) {
	now := l.now()
	number, err := cleanText(in.Number)
	if err != nil {
		return nil, fmt.Errorf("计划编号无效：%w", err)
	}
	instID, err := cleanText(in.InstrumentID)
	if err != nil {
		return nil, fmt.Errorf("器具编号无效：%w", err)
	}
	note, err := cleanText(in.Note)
	if err != nil {
		return nil, fmt.Errorf("计划说明无效：%w", err)
	}
	if l.findInstrument(instID) == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", instID, ErrNotFound)
	}
	dateText, err := l.validatePlanDate(in.Date, "计划日期", now)
	if err != nil {
		return nil, err
	}
	if l.findPlan(number) != nil {
		return nil, validationError("计划编号 %s 已存在，编号必须全台账唯一且不能复用", number)
	}
	for i := range l.data.Plans {
		p := &l.data.Plans[i]
		if p.InstrumentID == instID && p.Open() {
			return nil, validationError(
				"器具 %s 已有未结束的计划 %s（计划日期 %s），每件器具最多一项未结束计划",
				instID, p.Number, p.PlannedDate)
		}
	}
	p := Plan{
		Number:       number,
		InstrumentID: instID,
		PlannedDate:  dateText,
		OriginalDate: dateText,
		Note:         note,
		CreatedAt:    now.Format(time.RFC3339),
		Status:       PlanStatusOpen,
	}
	// 在独立的新切片上暂存新计划：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片，保证同一台账对象随后看到的计划查询、待办与
	// 按器具核对都与建立前一致——失败计划不占用编号或该器具唯一的未结束
	// 计划名额，再次提交仍会走到保存而不会被当成重复计划拒绝，失败计划也
	// 不会被之后的写盘顺带写入。
	original := l.data.Plans
	staged := make([]Plan, 0, len(original)+1)
	staged = append(staged, original...)
	staged = append(staged, p)
	l.data.Plans = staged
	if err := l.save(); err != nil {
		l.data.Plans = original
		return nil, err
	}
	return clonePlanPtr(l.findPlan(number)), nil
}

// requireOpenPlan 找到计划并确认其尚未结束；已结束计划返回明确的校验错误。
func (l *Ledger) requireOpenPlan(number string) (*Plan, error) {
	p := l.findPlan(number)
	if p == nil {
		return nil, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
	}
	if !p.Open() {
		return nil, validationError("计划 %s %s，已结束的计划不能再改期、取消或重新开启",
			number, p.Status)
	}
	return p, nil
}

// ReschedulePlan 改期一项未结束的计划。原因必须非空，新日期必须真实存在且
// 不早于操作当天；每次改期保留修改前后的日期、操作时间和原因。
// 找不到计划或计划已结束时拒绝且不改动记录。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的核对、计划查询与待办）与改期前完全一致——当前计划
// 日期不改变，失败申请的原因和时间既不进入改期历史、不改变待办标记，也不会
// 在此后其他成功操作写盘时被顺带写入；恢复可写后重新提交才按当时时间生效，
// 且只新增一条从最后成功保存的日期到新日期的记录。
//
// 返回的计划（含改期历史）是已保存内容的独立展示副本：调用方改动其中的
// 当前日期、状态或任意一条改期记录的原因、前后日期、操作时间，调换、删去
// 或追加列表记录，都只影响自己手中的那一份，不改写正式计划，也不影响
// 此前分别取得的操作结果、计划查询结果和核对结果。
func (l *Ledger) ReschedulePlan(number, newDate, reason string) (*Plan, error) {
	// 本次改期只取一次本机时间：新日期的合法性判断与留痕的操作时间对应
	// 同一时刻，跨午夜不会分裂到两天。
	now := l.now()
	number, err := cleanText(number)
	if err != nil {
		return nil, fmt.Errorf("计划编号无效：%w", err)
	}
	reason, err = cleanText(reason)
	if err != nil {
		return nil, fmt.Errorf("改期原因无效：%w", err)
	}
	dateText, err := l.validatePlanDate(newDate, "新计划日期", now)
	if err != nil {
		return nil, err
	}
	p, err := l.requireOpenPlan(number)
	if err != nil {
		return nil, err
	}
	// 即使新日期与当前日期相同也照常记录：保留修改前后的日期、操作时间和原因。
	change := PlanChange{
		From:      p.PlannedDate,
		To:        dateText,
		ChangedAt: now.Format(time.RFC3339),
		Reason:    reason,
	}
	// 在整份计划切片的独立副本上暂存改期：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片（含原计划日期与改期历史），保证同一台账对象随后看到的
	// 计划日期、改期历史与待办标记都与改期前一致，且不会被之后的写盘顺带写入。
	original := l.data.Plans
	staged := make([]Plan, len(original))
	copy(staged, original)
	for i := range staged {
		if staged[i].Number != number {
			continue
		}
		staged[i].Changes = append(append([]PlanChange(nil), staged[i].Changes...), change)
		staged[i].PlannedDate = dateText
	}
	l.data.Plans = staged
	if err := l.save(); err != nil {
		l.data.Plans = original
		return nil, err
	}
	return clonePlanPtr(l.findPlan(number)), nil
}

// CancelPlan 取消一项未结束的计划，原因必须非空。取消后保留原计划、取消时间
// 和原因，不再列入待办，也不能重新开启。找不到计划或计划已结束时拒绝。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的计划查询、按器具核对与待办）与取消前完全一致——
// 计划仍为未完成并继续列入待办，取消时间和原因不留下本次申请的内容，也不会
// 在此后其他成功操作写盘时被顺带写入；文件仍不可写时再次提交仍报保存错误
// （不会被当成“已结束”拒绝），恢复可写后无需重新打开台账，重新提交才真正
// 取消，取消时间和原因取本次成功提交而非失败那次。
//
// 返回的取消结果是独立展示副本：调用方把状态改回未完成或清空取消信息，
// 只影响自己那一份，正式计划仍保持已取消且不再列入待办。
func (l *Ledger) CancelPlan(number, reason string) (*Plan, error) {
	number, err := cleanText(number)
	if err != nil {
		return nil, fmt.Errorf("计划编号无效：%w", err)
	}
	reason, err = cleanText(reason)
	if err != nil {
		return nil, fmt.Errorf("取消原因无效：%w", err)
	}
	if _, err := l.requireOpenPlan(number); err != nil {
		return nil, err
	}
	canceledAt := l.now().Format(time.RFC3339)
	// 在整份计划切片的独立副本上暂存取消：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片（计划仍为未完成、取消时间与原因为空），保证同一
	// 台账对象随后看到的计划状态、待办与核对都与取消前一致，再次提交不会被
	// 当成“已结束”，失败信息也不会被之后的写盘顺带写入。
	original := l.data.Plans
	staged := make([]Plan, len(original))
	copy(staged, original)
	for i := range staged {
		if staged[i].Number != number {
			continue
		}
		staged[i].Status = PlanStatusCanceled
		staged[i].CanceledAt = canceledAt
		staged[i].CancelReason = reason
	}
	l.data.Plans = staged
	if err := l.save(); err != nil {
		l.data.Plans = original
		return nil, err
	}
	return clonePlanPtr(l.findPlan(number)), nil
}

// CompletePlan 用一张台账中已有的证书完成计划。证书必须属于该器具，校准日期
// 不得早于计划最初建立的本机日期，且未被用于完成其他计划。符合条件后保存
// 完成时间和证书编号；超差证书同样表示校准工作已完成。
//
// 业务校验全部通过后才写盘：若台账文件无法写入或替换，明确返回保存错误，
// 台账（含同一对象随后的计划查询、按器具核对与待办）与完成前完全一致——
// 计划仍为未完成并继续列入待办，完成时间与关联证书编号保持操作前的值，
// 计划日期、已有改期记录和待办日期标记都不改变，该证书也不会被算作已用于
// 完成计划（既不会被随后的提交当成“此前已完成”跳过保存，也不会被其他成功
// 写盘顺带写入文件）；恢复可写后无需重新打开台账，重新提交才真正完成，
// 完成时间取本次成功操作而非失败时刻。
//
// 再次用同一证书完成同一已保存为完成的计划返回原结果，不增加记录或刷新
// 完成时间；已完成计划改用另一证书、证书不存在或不符合条件、完成已取消
// 计划均拒绝。
//
// 返回的完成结果（含再次完成返回的原结果）是独立展示副本：调用方把它改成
// 未完成或换掉证书编号，正式计划仍保持完成，原证书仍算已用于该计划，不能
// 因此拿去完成另一项计划，完成时间也不会被刷新。
func (l *Ledger) CompletePlan(number, certificateNumber string) (*Plan, bool, error) {
	number, err := cleanText(number)
	if err != nil {
		return nil, false, fmt.Errorf("计划编号无效：%w", err)
	}
	certificateNumber, err = cleanText(certificateNumber)
	if err != nil {
		return nil, false, fmt.Errorf("证书编号无效：%w", err)
	}
	p := l.findPlan(number)
	if p == nil {
		return nil, false, fmt.Errorf("计划编号 %s：%w", number, ErrNotFound)
	}
	// 幂等：同一证书再次完成同一计划，返回原结果，不刷新完成时间。
	// 返回的同样是独立副本：即使把它改成未完成或换掉证书编号，正式计划
	// 仍保持完成、原证书仍算已用于该计划。
	if p.Status == PlanStatusDone {
		if p.CertificateNumber == certificateNumber {
			return clonePlanPtr(p), true, nil
		}
		return nil, false, validationError(
			"计划 %s 已用证书 %s 完成，已完成计划不能改用另一证书",
			number, p.CertificateNumber)
	}
	if p.Status == PlanStatusCanceled {
		return nil, false, validationError("计划 %s 已取消，取消的计划不能完成；需要继续安排请建立新计划", number)
	}

	cert := l.findCertificate(certificateNumber)
	if cert == nil {
		return nil, false, fmt.Errorf("证书编号 %s：%w", certificateNumber, ErrNotFound)
	}
	if cert.InstrumentID != p.InstrumentID {
		return nil, false, validationError(
			"证书 %s 属于器具 %s，不能用于完成器具 %s 的计划 %s",
			certificateNumber, cert.InstrumentID, p.InstrumentID, number)
	}
	// 计划建立的本机日期：CreatedAt 是带“建立当时时区偏移”的 RFC3339。
	// time.Parse 返回的时刻自带该固定偏移，直接 Format 取到的就是建立时所在的
	// 本机日历日期；绝不能先 In(time.Local) 或 .UTC() 换算再取日——完成操作
	// 可能发生在另一个时区（或本机此后切换了时区），换算会把跨日的建立时刻移到
	// 相邻的日历日：东八区凌晨（00:30+08:00）换算 UTC 落到前一天、西七区深夜
	// （23:30-07:00）换算 UTC 落到后一天，都会使日期界限被错误地提前或推后。
	// 界限锚定在记录保存的偏移所表示的那一天上，与本次运行的时区、日期无关。
	// 与证书校准日期按日历日期比较，校准日期不得早于该日期（等于可以）；
	// 证书只记载日期、没有时分秒，建立当天的证书不因建立钟点较晚而被判过早。
	created, perr := time.Parse(time.RFC3339, p.CreatedAt)
	if perr != nil {
		return nil, false, fmt.Errorf("计划 %s 建立时间已损坏: %w", number, perr)
	}
	createdDay := created.Format(DateLayout)
	if cert.CalDate < createdDay {
		return nil, false, validationError(
			"证书 %s 的校准日期 %s 早于计划 %s 的建立日期 %s，不能用于完成该计划",
			certificateNumber, cert.CalDate, number, createdDay)
	}
	// 同一证书不能用于完成两项计划；以幂等方式再次完成本计划已在前面处理。
	for i := range l.data.Plans {
		other := &l.data.Plans[i]
		if other.Number != number && other.Status == PlanStatusDone &&
			other.CertificateNumber == certificateNumber {
			return nil, false, validationError(
				"证书 %s 已用于完成计划 %s，不能再用于完成其他计划",
				certificateNumber, other.Number)
		}
	}

	completedAt := l.now().Format(time.RFC3339)
	// 在整份计划切片的独立副本上暂存完成：只有原子替换台账文件成功后才提交。
	// 写盘失败时恢复原切片（计划仍为未完成、完成时间与关联证书编号为空），
	// 保证同一台账对象随后看到的计划状态、待办与证书占用都与完成前一致，
	// 再次提交不会被当成“此前已完成”，失败信息也不会被之后的写盘顺带写入。
	original := l.data.Plans
	staged := make([]Plan, len(original))
	copy(staged, original)
	for i := range staged {
		if staged[i].Number != number {
			continue
		}
		staged[i].Status = PlanStatusDone
		staged[i].CompletedAt = completedAt
		staged[i].CertificateNumber = certificateNumber
	}
	l.data.Plans = staged
	if err := l.save(); err != nil {
		l.data.Plans = original
		return nil, false, err
	}
	return clonePlanPtr(l.findPlan(number)), false, nil
}

// TodoItem 是待办查询中的一项计划及其按本机日期重新判断的标记。
type TodoItem struct {
	PlanNumber     string `json:"plan_number"`
	InstrumentID   string `json:"instrument_id"`
	InstrumentName string `json:"instrument_name"`
	Status         Status `json:"status"`
	PlannedDate    string `json:"planned_date"`
	Note           string `json:"note"`
	Marker         string `json:"marker"`
}

// planMarker 按计划日期相对今天给出标记：今天“今天需校准”，已过“逾期”，
// 未来“未到计划日”。
func planMarker(plannedDate, todayText string) string {
	switch {
	case plannedDate < todayText:
		return TodoOverdue
	case plannedDate == todayText:
		return TodoToday
	default:
		return TodoFuture
	}
}

// Todos 列出未结束的计划作为待办。instrumentID 为空时列出全部器具的待办，
// 否则只列该器具（器具不存在时报 ErrNotFound）。结果按计划日期从早到晚、
// 同日按器具编号排列。查询不产生任何使用记录或写盘。
func (l *Ledger) Todos(instrumentID string) ([]TodoItem, error) {
	id := strings.TrimSpace(instrumentID)
	if id != "" && l.findInstrument(id) == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
	}
	todayText := l.now().Format(DateLayout)
	items := []TodoItem{}
	for _, p := range l.data.Plans {
		if !p.Open() {
			continue
		}
		if id != "" && p.InstrumentID != id {
			continue
		}
		inst := l.findInstrument(p.InstrumentID)
		if inst == nil {
			continue
		}
		items = append(items, TodoItem{
			PlanNumber:     p.Number,
			InstrumentID:   inst.ID,
			InstrumentName: inst.Name,
			Status:         inst.Status,
			PlannedDate:    p.PlannedDate,
			Note:           p.Note,
			Marker:         planMarker(p.PlannedDate, todayText),
		})
	}
	sort.Slice(items, func(i, j int) bool {
		if items[i].PlannedDate != items[j].PlannedDate {
			return items[i].PlannedDate < items[j].PlannedDate
		}
		return items[i].InstrumentID < items[j].InstrumentID
	})
	return items, nil
}

// PlanView 是计划的完整视图，供按器具核对时展示当前与已结束计划、
// 改期记录和关联证书编号。
type PlanView struct {
	Plan
	Marker string `json:"marker"`
}

// plansOf 返回某器具的全部计划（含已结束），按建立的实际时刻从早到晚排列。
// 返回的是深拷贝（含改期历史）：调用方整理按器具查询或核对结果中的
// 计划与改期记录，不会回写台账，也不会影响此前或之后分别取得的其他结果。
//
// CreatedAt 是带偏移的 RFC3339 时间：同一件器具的计划可能在不同系统时区
// 偏移下（含 Z 与显式零偏移）先后建立。排序换算为同一基准下的绝对时刻，
// 因此不能按时间文字里的日期、小时大小判断先后——文字日期更小或小时更小
// 的记录未必更早，跨日记录也按实际时刻排列；各记录保存时自带的偏移决定
// 先后，查询当天的系统时区不能改变这些历史的先后关系。已完成、已取消与
// 未完成的计划一起参与排序，状态、当前计划日期、改期时间与完成时间均不作
// 排序条件。实际时刻相同的记录（即使分别使用 Z、+00:00 或其他偏移）由
// SliceStable 保留其在台账中的原有次序，每项都单独保留、不合并。
func (l *Ledger) plansOf(id string) []Plan {
	var out []Plan
	for _, p := range l.data.Plans {
		if p.InstrumentID == id {
			out = append(out, clonePlan(p))
		}
	}
	sort.SliceStable(out, func(i, j int) bool {
		ti, oki := parseInstant(out[i].CreatedAt)
		tj, okj := parseInstant(out[j].CreatedAt)
		switch {
		case oki && okj:
			// 按实际时刻比较：Equal/Before 以绝对时刻为准，与记录建立时
			// 所带的偏移及文字形式无关；时刻相同时返回 false，交由
			// SliceStable 保留它们在台账中的原有次序。
			return ti.Before(tj)
		case oki != okj:
			// 时间文字无法解析的异常记录排到可解析记录之后，顺序仍确定；
			// 正常由本台账保存的 RFC3339 记录不会走到这里。
			return oki
		default:
			// 两条都无法解析时退回按原文字比较，保证结果确定。
			return out[i].CreatedAt < out[j].CreatedAt
		}
	})
	return out
}

// planViews 构造器具核对用的计划视图；标记仅对未结束计划有意义。
func (l *Ledger) planViews(id string, today time.Time) []PlanView {
	todayText := today.Format(DateLayout)
	plans := l.plansOf(id)
	out := make([]PlanView, 0, len(plans))
	for _, p := range plans {
		v := PlanView{Plan: p}
		if p.Open() {
			v.Marker = planMarker(p.PlannedDate, todayText)
		}
		out = append(out, v)
	}
	return out
}

// Plans 返回某器具的全部计划（含已完成、已取消与未完成），按建立的实际
// 时刻从早到晚排列；器具不存在时报 ErrNotFound。
//
// CreatedAt 是带偏移的 RFC3339 时间：同一件器具的计划可能在不同系统时区
// 偏移下（含 Z 与显式零偏移）先后建立，排序换算为同一基准下的绝对时刻，
// 因此显示文字里日期、小时更大的计划未必更晚，跨日计划也按实际时刻排列；
// 各计划保存时自带的偏移决定先后，查询当天的系统时区不能改变历史顺序。
// 已完成、已取消与未完成的计划一起参与排序，计划状态、当前计划日期、改期
// 时间与完成时间均不作为排序条件。实际时刻相同的计划（即使分别使用 Z、
// +00:00 或其他偏移）保留其在台账中的原有次序，每项都单独返回、不合并。
//
// 返回的计划（含改期历史）都是独立展示副本：建立时间保留原文字及偏移，
// 计划日期、改期历史、取消信息及关联证书编号都保持保存时的内容；调用方
// 调换顺序、删改或追加记录或改动任何字段，只影响自己手中的结果，不回写
// 台账，也不影响此前或之后分别取得的操作结果与核对结果。查询不写盘。
func (l *Ledger) Plans(instrumentID string) ([]PlanView, error) {
	id := strings.TrimSpace(instrumentID)
	inst := l.findInstrument(id)
	if inst == nil {
		return nil, fmt.Errorf("器具编号 %s：%w", id, ErrNotFound)
	}
	return l.planViews(id, l.now()), nil
}

