362	func cmdUse(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
363		fs := newFlagSet("use", &opts)
364		id := fs.String("id", "", "器具编号")
365		if err := fs.Parse(args); err != nil {
366			fmt.Fprintln(stderr, "use 参数错误：", err)
367			return 2
368		}
369		if strings.TrimSpace(*id) == "" {
370			fmt.Fprintln(stderr, "use 必须提供 --id")
371			return 2
372		}
373		d, err := l.RequestUse(*id)
374		if err != nil {
375			if errors.Is(err, calibrate.ErrNotFound) || calibrate.IsValidation(err) {
376				return failBusiness(opts, stdout, stderr, err,
377					map[string]any{"accepted": false, "recorded": false, "error": err.Error()})
378			}
379			return failIO(stderr, err)
380		}
381		if !d.Allowed {
382			var sb strings.Builder
383			sb.WriteString(fmt.Sprintf("拒绝使用器具 %s，已记录本次拒绝及原因：\n", *id))
384			for _, r := range d.Reasons {
385				sb.WriteString("  - " + r + "\n")
386			}
387			if opts.asJSON {
388				raw, _ := json.MarshalIndent(map[string]any{
389					"allowed": false, "recorded": true, "decision": d,
390				}, "", "  ")
391				fmt.Fprintln(stdout, string(raw))
392			}
393			fmt.Fprint(stderr, sb.String())
394			return 1
395		}
396		human := fmt.Sprintf("允许使用器具 %s，已记录本次申请。\n", *id)
397		return emit(opts, stdout, stderr, human,
398			map[string]any{"allowed": true, "recorded": true, "decision": d})
399	}
